INSERT INTO "Products" ("ProductId", "SellerId", "CategoryId", "Name", "Description", "Price", "ProductionDays", "CustomSizeSupported", "Status", "CreatedAt", "UpdatedAt", "Height", "Length", "Width") VALUES (11, 5, 5, 'Bộ 3 Tranh Tráng Gương Pha Lê Cửu Ngư Quần Hội & Sen Ngọc', 'Bộ 3 tranh tráng gương pha lê cao cấp Cửu Ngư Quần Hội kết hợp đóa sen ngọc bích phát tài phát lộc. Bề mặt phủ bóng ceramic chống bám bụi, viền khung composite titan sang trọng, phù hợp trang trí phòng khách, phòng làm việc theo phong thủy thu hút tài lộc.', 1850000.00, 3, true, 'ACTIVE', '2026-09-21T16:11:24.2218571', '2026-09-21T16:11:24.2218573', 80, 180, 5);
INSERT INTO "Products" ("ProductId", "SellerId", "CategoryId", "Name", "Description", "Price", "ProductionDays", "CustomSizeSupported", "Status", "CreatedAt", "UpdatedAt", "Height", "Length", "Width") VALUES (12, 5, 5, 'Tranh Canvas Mái Nhà Cổ & Cây Hoa Ban Nắng Ấm Tây Bắc', 'Tranh nghệ thuật tái hiện khung cảnh thanh bình vùng cao Tây Bắc với mái ngói rêu phong, tường vàng ấm áp và cây hoa ban trắng bung nở dưới ánh nắng vàng nhẹ. Chất liệu vải canvas kim tuyến cán bóng hoặc tráng gương chống ẩm mốc, khung viền gỗ sồi tự nhiên mộc mạc tinh tế.', 1200000.00, 2, true, 'ACTIVE', '2026-09-21T16:11:24.2512752', '2026-09-21T16:11:24.2512757', 80, 120, 4);
INSERT INTO "Products" ("ProductId", "SellerId", "CategoryId", "Name", "Description", "Price", "ProductionDays", "CustomSizeSupported", "Status", "CreatedAt", "UpdatedAt", "Height", "Length", "Width") VALUES (13, 5, 5, 'Tranh Tráng Gương Sơn Thủy Hữu Tình Thác Nước Tùng Hạc', 'Bức tranh phong cảnh đại ngàn kỳ vĩ với thác nước luân chuyển tài lộc, đàn hạc tiên ngụ ý trường thọ và ánh bình minh rạng rỡ mang lại vượng khí cho gia chủ. Bề mặt tráng gương cao cấp siêu nét 8K, đèn LED hắt sáng viền lưng tạo chiều sâu cho không gian phòng khách hiện đại.', 2350000.00, 4, true, 'ACTIVE', '2026-09-21T16:11:24.2517618', '2026-09-21T16:11:24.2517619', 80, 160, 5);
INSERT INTO "Products" ("ProductId", "SellerId", "CategoryId", "Name", "Description", "Price", "ProductionDays", "CustomSizeSupported", "Status", "CreatedAt", "UpdatedAt", "Height", "Length", "Width") VALUES (14, 5, 5, 'Bộ Đôi Tranh Canvas Scandinavian Dương Xỉ Nhiệt Đới & Hoa Hồng', 'Bộ 2 tranh đối xứng phong cách Scandinavian tối giản hiện đại, kết hợp hài hòa giữa sắc xanh mướt của lá dương xỉ rừng nhiệt đới và sắc hồng dịu dàng của bụi hoa hồng Pháp. Mang lại cảm giác thư thái, gần gũi thiên nhiên cho phòng ngủ, phòng khách hoặc căn hộ studio.', 950000.00, 2, true, 'ACTIVE', '2026-09-21T16:11:24.2519837', '2026-09-21T16:11:24.2519837', 70, 100, 3);
INSERT INTO "Products" ("ProductId", "SellerId", "CategoryId", "Name", "Description", "Price", "ProductionDays", "CustomSizeSupported", "Status", "CreatedAt", "UpdatedAt", "Height", "Length", "Width") VALUES (15, 5, 5, 'Tranh Phong Thủy Chữ An Thư Pháp & Hoa Mẫu Đơn Kim Hoàng', 'Bức tranh nghệ thuật thư pháp chữ ''An'' kết hợp câu chúc ''Gia đình vạn sự bình yên - Tài vô lộc đến phúc duyên tràn đầy'' và chùm hoa mẫu đơn mạ vàng sang trọng. Biểu trưng cho cuộc sống an lành, thịnh vượng, phú quý và hạnh phúc viên mãn. Rất thích hợp làm quà tân gia, mừng thọ hoặc bài trí phòng khách gia đình.', 2100000.00, 3, true, 'ACTIVE', '2026-09-21T16:11:24.2521936', '2026-09-21T16:11:24.2521936', 70, 140, 4);
